import express, { type RequestHandler } from 'express';
import { mkdir, unlink, writeFile } from 'node:fs/promises';
import path from 'node:path';

import type { FileStorage } from './file-storage';

// Keys are generated by the server, but check anyway so a bad key can never
// reach outside the uploads directory (e.g. "../../etc/passwd").
const SAFE_KEY = /^[a-z0-9-]+(\/[a-z0-9-]+)*\.[a-z0-9]+$/;

const resolveKey = (directory: string, key: string): string => {
  if (!SAFE_KEY.test(key)) {
    throw new Error(`Unsafe storage key: ${key}`);
  }

  return path.join(directory, key);
};

/** Files on the API server's disk, served by `serveLocalFiles`. */
export const createLocalFileStorage = ({
  directory,
  baseUrl,
}: {
  directory: string;
  baseUrl: string;
}): FileStorage => ({
  save: async (key, data) => {
    const filePath = resolveKey(directory, key);

    await mkdir(path.dirname(filePath), { recursive: true });
    await writeFile(filePath, data);
  },

  delete: async (key) => {
    try {
      await unlink(resolveKey(directory, key));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
        throw error;
      }
    }
  },

  publicUrl: (key) => `${baseUrl}/${key}`,
});

/**
 * Serves stored files. Names are random and never reused, so browsers may
 * cache them forever. `nosniff` stops a browser from treating a file as
 * anything other than its declared image type.
 */
export const serveLocalFiles = (directory: string): RequestHandler =>
  express.static(directory, {
    index: false,
    redirect: false,
    dotfiles: 'deny',
    immutable: true,
    maxAge: '1y',
    setHeaders: (res) => {
      res.setHeader('X-Content-Type-Options', 'nosniff');
    },
  });
